let B(skB, pkA) =
  let pkB = pk(skB) in
  in(<sig, enc>);
  if verify(sig, enc, pkA) = true then (
    let plain = adec(enc, skB) in
    let pk_recv = fst(plain) in
    let na = snd(plain) in
    if pk_recv = pkA then (
      let m = <sig, enc> in
      event Role('B');
      event Recv(pkB, m);
      event Secret_B(na, pkB);
      event End()
    )
  )
